import{_ as e,C as s,o as n,c as o,j as d,a as r,E as l,a3 as i}from"./chunks/framework.Brvjz8oQ.js";const y=JSON.parse('{"title":"評測迭代 v1–v8","description":"","frontmatter":{},"headers":[],"relativePath":"eval.md","filePath":"eval.md"}'),h={name:"eval.md"};function b(u,t,m,g,v,c){const a=s("EvalChart");return n(),o("div",null,[t[0]||(t[0]=d("h1",{id:"評測迭代-v1–v8",tabindex:"-1"},[r("評測迭代 v1–v8 "),d("a",{class:"header-anchor",href:"#評測迭代-v1–v8","aria-label":'Permalink to "評測迭代 v1–v8"'},"​")],-1)),t[1]||(t[1]=d("p",null,[r("不憑感覺調參:45 條真實查詢的自動評測 harness("),d("strong",null,"LLM-as-judge"),r(" 對每個 query × top-5 結果打相關度),每輪改動都跑分 — 贏的留、輸的回滾。")],-1)),l(a),t[2]||(t[2]=i('<h2 id="名詞解釋" tabindex="-1">名詞解釋 <a class="header-anchor" href="#名詞解釋" aria-label="Permalink to &quot;名詞解釋&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>白話</th><th>1.0 的意思</th></tr></thead><tbody><tr><td><strong>nDCG@5</strong></td><td>前 5 名的「排序品質」— 對的片排得越前面分數越高,排對位置比只是有出現更重要</td><td>理想排序:最相關的剛好都排最前</td></tr><tr><td><strong>MRR</strong></td><td>第一個相關結果平均出現在第幾名(取倒數)— 衡量「第一名直接就對」的能力</td><td>每一條查詢的第 1 名都相關</td></tr><tr><td><strong>P@5</strong></td><td>前 5 名裡相關影片的比例 — 不管順序,只看命中率</td><td>前 5 名全部相關</td></tr></tbody></table><h2 id="各版本一覽" tabindex="-1">各版本一覽 <a class="header-anchor" href="#各版本一覽" aria-label="Permalink to &quot;各版本一覽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>改了什麼</th><th>nDCG@5</th><th>MRR</th><th>P@5</th><th>結論</th></tr></thead><tbody><tr><td>v1</td><td>baseline(hybrid + RRF)</td><td>0.9307</td><td>0.925</td><td>0.86</td><td>起點</td></tr><tr><td>v2</td><td>多項 gating 一起上</td><td>0.9255</td><td>0.9167</td><td>0.84</td><td>回退 — 一次改太多</td></tr><tr><td><strong>v3</strong></td><td>只留 parser alias</td><td><strong>0.9512</strong></td><td>0.925</td><td><strong>0.89</strong></td><td>第一個大贏</td></tr><tr><td>v4</td><td>+ 英文域 reranker</td><td>0.9368</td><td>0.925</td><td>0.73</td><td>選錯模型,精確度掉</td></tr><tr><td>v5</td><td>step-back 全開</td><td>0.9350</td><td>0.925</td><td>0.85</td><td>幫模糊查詢、傷具體查詢</td></tr><tr><td><strong>v6</strong></td><td>step-back 改條件觸發</td><td>0.9623</td><td><strong>1.000</strong></td><td>0.84</td><td>MRR 滿分 ⭐</td></tr><tr><td>v7</td><td>再試英文域 reranker</td><td>0.9368</td><td>0.9417</td><td>0.79</td><td>確認是模型問題</td></tr><tr><td><strong>v8</strong></td><td>換中文域 reranker(bce)</td><td><strong>0.9625</strong></td><td>0.975</td><td><strong>0.89</strong></td><td>均衡最佳 ⭐</td></tr></tbody></table><h2 id="迭代手記-—-每一版在想什麼" tabindex="-1">迭代手記 — 每一版在想什麼 <a class="header-anchor" href="#迭代手記-—-每一版在想什麼" aria-label="Permalink to &quot;迭代手記 — 每一版在想什麼&quot;">​</a></h2><details class="note"><summary>v1 — 先量再動</summary> 動手調參前先立尺:雙路召回 + RRF + 加權 boost 的素管線直接跑分,0.9307。沒有 baseline 的優化都是自我感覺良好。 </details><details class="note"><summary>v2 — 貪心:四個想法一起上,整體回退</summary> 當時覺得 query 理解有四個明顯可改(關鍵字對照表、展開降權、維度過濾、跳過展開),都對就全上。結果 -0.005:3 條變好、5 條變差,而且互相打架,根本分不出誰的功勞誰的鍋。<br><b class="turn">→ 轉折:從此一輪只動一個變因。這個紀律比任何單一技巧值錢。</b></details><details class="note"><summary>v3 — 拆開重來,只留一個:第一個大贏</summary> 把 v2 四件事拆開,只留「關鍵字對照表」(英文別名 + 50 個中文類型詞 + 得獎詞)。+0.02 → 0.9512,「韓國犯罪驚悚」「得獎」「監獄」這些之前完全漏接的訊號全接住了。<br><b class="turn">→ 學到:擴充對照表是純賺,沒有副作用,值得一直補。</b></details><details class="note"><summary>v4 — 第一次上精排模型:翻車</summary> 直覺上「多一層精排一定更準」。掛上英文域訓練的 reranker,反而 -0.014,前五命中率掉到 0.73。<br><b class="turn">→ 學到:它是在英文資料上學的「相關」,看不懂中文片庫;「多一層 AI」不保證更好。</b></details><details class="note"><summary>v5 — 抽象化查詢:幫了模糊的,傷了具體的</summary> 讓 LLM 把查詢「抽象化」(「被仙人跳分手療傷」→「失戀療癒」)再多召回一路。模糊查詢 +1,但 6 條具體查詢(「香港警匪片」「監獄」…)被拉進雜訊,淨輸。<br><b class="turn">→ 轉折:這招是雙面刃,問題不是「要不要用」,是「什麼時候用」。</b></details><details class="note"><summary>v6 — 同一招,加個開關:MRR 滿分 ⭐</summary> 只在「查詢裡抓不到任何具體條件」時才啟用抽象化。0.9623,每一條查詢的第一名都對(MRR 1.0)。<br><b class="turn">→ 學到:v2 教訓真正的形狀 — gating 不是不能做,是要鎖在最小的那顆旋鈕上。</b></details><details class="note"><summary>v7 — 不死心再試英文 reranker:確認是模型的鍋</summary> 給它補上年份/地區/卡司資訊、改成位置感知混分 — 架構上全對,分數還是 0.9368。<br><b class="turn">→ 學到:架構修補救不了選錯模型。兩輪失敗把問題定位釘死了。</b></details><details class="note"><summary>v8 — 換中文域 reranker:均衡最佳 ⭐</summary> 同一個 API 介面,換成中文 IR 訓練的 bce 模型。nDCG 持平 0.9625,但前五命中率 +0.05、評測零失敗 — 精排終於開始賺錢。<br><b class="turn">→ 學到:reranker 的語言域比架構重要;對的模型讓 v4/v7 全部的架構工作瞬間生效。</b></details><h2 id="幾個有代表性的教訓" tabindex="-1">幾個有代表性的教訓 <a class="header-anchor" href="#幾個有代表性的教訓" aria-label="Permalink to &quot;幾個有代表性的教訓&quot;">​</a></h2><ul><li><strong>一次只改一件事</strong> — v2 把四個想法一起上,整體回退;v3 拆開只留一個,+0.02。</li><li><strong>step-back 抽象查詢向量是雙面刃</strong> — 模糊查詢(「被仙人跳分手療傷」)受益,具體查詢(「香港警匪片」)被拉進雜訊;v6 改成「parser 抓不到具體條件才啟用」後 MRR 1.0。</li><li><strong>reranker 的語言域比架構重要</strong> — 同 API 介面,英文域模型連兩輪扣分,換中文域訓練的 bce 立刻 nDCG +0.026、P@5 +0.10。</li></ul><h2 id="附註-換一把更省電的尺-—-judge-的模型與硬體" tabindex="-1">附註:換一把更省電的尺 — judge 的模型與硬體 <a class="header-anchor" href="#附註-換一把更省電的尺-—-judge-的模型與硬體" aria-label="Permalink to &quot;附註:換一把更省電的尺 — judge 的模型與硬體&quot;">​</a></h2><p>評測的打分者(LLM judge)<strong>全程都是本地模型</strong>。為什麼不用雲端?一輪評測是 45 條查詢 × top-5 = 最多 225 次打分,11 輪迭代下來逼近 2,500 次 — 走雲端免費額度馬上撞限流,還會跟產品本身的 LLM 配額互搶;本地 judge 零邊際成本、隨時重跑、結果可重現(同模型同 prompt,分數不會因服務端改版而漂)。</p><p>v1–v8 用較大的 MoE 模型(35B-A3B,跑在 GPU);後來換成小一號的 <strong>8B dense 模型跑在 NPU</strong> 重評 —<strong>模型不同 = 尺不同,分數不能跟上面直接比</strong>,所以分開列:</p><table tabindex="0"><thead><tr><th>輪次</th><th>範圍</th><th>nDCG@5</th><th>MRR</th><th>結論</th></tr></thead><tbody><tr><td>8B judge @ NPU(子集)</td><td>20 條查詢</td><td>0.9286</td><td>0.9417</td><td>小模型 + NPU 評測管線跑通</td></tr><tr><td>8B judge @ NPU(全量)</td><td>45 條查詢</td><td>0.9233</td><td>0.9444</td><td>持續穩定 — 評測可低功耗長跑,不佔 GPU</td></tr></tbody></table>',19))])}const P=e(h,[["render",b]]);export{y as __pageData,P as default};
